mkdir -p /tmp/x; cat > src/orchestration/tools/registry.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('returns a rejection naming a missing required property and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: expect.stringMatching(/location.*required|required.*location/i),
    });
  });
});
EOF
NODE_OPTIONS=--experimental-vm-modules timeout 300 npx jest --runTestsByPath src/orchestration/tools/registry.test.ts 2>&1 | tail -20

